`timescale 1ns/1ps
// SIMULATION ONLY.  One die of rtl/test/tb_hdc_qwen_layer0_tp2.sv for runtime
// composition: the TP sequencer (ot_rom_tp_seq) and the core with its matrix
// engine cut into ot_qwen_rt_matvec_seq (inside ot_qwen_rt_core, generated by
// tools/qwen_rt_core_emit.py) plus host-composed slices.  The testbench's
// reset/start stimulus is kept here, register for register, so every die model
// sees the same edges as the monolithic bench.  All memories of the bench
// (program, descriptors, INT8 codes, scales, constants, VM, KV) are served by
// the host with the bench's read-before-write, registered-response semantics;
// the collective is a separate model wired by the host.
module ot_qwen_rt_die #(
    parameter integer G = 6144,
    parameter integer NW = 16,
    parameter integer SNW = 16,        // TP sequencer token width
    parameter integer QWEN_FULLSHAPE = 0,
    parameter integer ME_STALL = 0,
    parameter integer ME_IDLE_GATE = 0,
    parameter integer D = 2
) (
    input  wire              clk,
    output reg               rt_rst_n,
    output reg  [31:0]       cyc,
    output reg               start,
    input  wire [SNW-1:0]    tp_token,
    input  wire [SNW-1:0]    tp_pos,
    input  wire              h_start,
    input  wire              me_mem_ok,        // ME_STALL: weight supply serves the engine's current reads
    output wire              me_clk_en,        // ME_STALL: this edge clocks the engine (slices follow it)          // host stage controller (0 in the layer-0 bench replay)
    // sequencer status
    output wire              s_done,
    output wire              s_fault,
    output wire              core_fault,
    output wire [SNW-1:0]    seq_ntok,
    output wire [31:0]       seq_nval,
    output wire [31:0]       core_cycles,
    // collective side
    output wire              c_valid,
    input  wire              c_ready,
    output wire [511:0]      c_data,
    output wire              c_last,
    output wire              c_mode,
    output wire [31:0]       c_tag,
    input  wire              r_valid,
    input  wire [511:0]      r_data,
    input  wire              r_last,
    input  wire              r_rank,
    input  wire              r_err,
    // program / descriptors / sequencer VM word port
    output wire [11:0]       prog_base,
    output wire              prog_re,
    output wire [11:0]       prog_addr,
    input  wire [1023:0]     prog_q,
    output wire              desc_re,
    output wire [5:0]        desc_addr,
    input  wire [63:0]       desc_q,
    output wire              s_vre,
    output wire [7:0]        s_vraddr,
    input  wire [511:0]      s_vrq,
    output wire              s_vwe,
    output wire [7:0]        s_vwaddr,
    output wire [511:0]      s_vwdata,
    // core scalar memory ports
    output wire              wrom_re,
    output wire              int8_wrom_re,
    output wire [23:0]       int8_wrom_addr,
    output wire              scale_re,
    output wire              crom_re,
    output wire [23:0]       crom_addr,
    input  wire [63:0]       crom_q,
    output wire              kv_re,
    output wire              kv_we,
    output wire [23:0]       kv_waddr,
    output wire [31:0]       kv_wdata,
    output wire              va_re, vb_re, vc_re,
    output wire [23:0]       va_addr, vb_addr, vc_addr,
    input  wire [31:0]       va_q, vb_q, vc_q,
    output wire              vw_su_we,
    output wire [23:0]       vw_su_addr,
    output wire [31:0]       vw_su_data,
    output wire              vw_rd_we,
    output wire [23:0]       vw_rd_addr,
    output wire [31:0]       vw_rd_data,
    output wire              vw_mx_we,
    output wire [23:0]       vw_mx_addr,
    output wire [15:0]       vw_mx_mask,
    output wire [511:0]      vw_mx_data,
    output wire              me_ov,
    // matrix-engine slice broadcast / reductions (see ot_qwen_rt_matvec_seq)
    output wire              b_active,
    output wire [23:0]       b_cur,
    output wire [3:0]        b_split_r,
    output wire [23:0]       b_ts_r,
    output wire [23:0]       b_wcs_r,
    output wire [23:0]       b_xc,
    output wire [23:0]       b_xcs_r,
    output wire              b_wsrc_r,
    output wire [NW-1:0]     b_k,
    output wire [NW-1:0]     b_ktot_r,
    output wire              b_s1b_wsrc,
    output wire              b_s2_round,
    output wire              b_s3_v,
    output wire              b_fl_first4,
    output wire              b_vline5,
    output wire [$clog2(G)-1:0] b_reduce_valid,
    output wire [$clog2(G)-1:0] b_reduce_select,
    output wire              b_pre_v,
    output wire [3*(NW+1)+24+4+3-1:0] b_pre,
    output wire              b_raw_v,
    output wire [3*(NW+1)+4+3-1:0] b_raw,
    output wire              b_r_v,
    output wire [3*(NW+1)+2*24+4+3-1:0] b_r,
    input  wire              x_scale_any,
    input  wire              x_group_fault_q,
    input  wire              x_scale_fault,
    input  wire              x_tfault,
    input  wire [1+32+NW-1:0] x_top
);
    localparam integer W=16, AW=24, PAW=12, DAW=6, FW=512;
    // -- testbench stimulus, as tb_hdc_qwen_layer0_tp2 ------------------------
    initial begin rt_rst_n = 0; start = 0; cyc = 0; end
    always @(posedge clk) begin
        cyc <= cyc+1;
        if (cyc==5) rt_rst_n <= 1;
        if (cyc==7) start <= 1;
        if (cyc==8) start <= 0;
    end
    wire rst_n = rt_rst_n;

    wire core_start, core_done;
    wire [SNW-1:0] core_tok, core_pos, core_ntok;
    wire [31:0] core_nval;
    wire coll_busy;
    wire [NW-1:0] core_ntok_c;
    assign core_ntok = core_ntok_c;             // zero-extended when SNW > NW

    ot_qwen_rt_core #(.W(W),.G(G),.AW(AW),.NW(NW),.PAW(PAW),
        .INT8_WEIGHT(1),.INT8_SCALE_WCS_BASE(1),.INT8_EMBED(0),.QWEN_FULLSHAPE(QWEN_FULLSHAPE),
        .ME_STALL(ME_STALL),.ME_IDLE_GATE(ME_IDLE_GATE)) core (
        .clk(clk),.rst_n(rst_n),.start(core_start),.token(core_tok[NW-1:0]),.pos(core_pos[NW-1:0]),
        .done(core_done),.next_token(core_ntok_c),.next_val(core_nval),
        .cycles(core_cycles),.fault(core_fault),
        .prog_re(prog_re),.prog_addr(prog_addr),.prog_q(prog_q),
        .wrom_re(wrom_re),.wrom_addr(),.wrom_q({(G*W*16){1'b0}}),
        .int8_wrom_re(int8_wrom_re),.int8_wrom_addr(int8_wrom_addr),
        .scale_re(scale_re),
        .embed_code_q(512'd0),.embed_scale_q(16'd0),
        .crom_re(crom_re),.crom_addr(crom_addr),.crom_q(crom_q),
        .kv_re(kv_re),
        .kv_we(kv_we),.kv_waddr(kv_waddr),.kv_wdata(kv_wdata),
        .va_re(va_re),.va_addr(va_addr),.va_q(va_q),
        .vb_re(vb_re),.vb_addr(vb_addr),.vb_q(vb_q),
        .vc_re(vc_re),.vc_addr(vc_addr),.vc_q(vc_q),
        .vw_mx_we(vw_mx_we),.vw_mx_addr(vw_mx_addr),.vw_mx_mask(vw_mx_mask),.vw_mx_data(vw_mx_data),
        .vw_su_we(vw_su_we),.vw_su_addr(vw_su_addr),.vw_su_data(vw_su_data),
        .vw_rd_we(vw_rd_we),.vw_rd_addr(vw_rd_addr),.vw_rd_data(vw_rd_data),
        .me_ov(me_ov),
        .kv_ok(1'b1),.kv_write_drained(1'b1),.w_ok(1'b1),.emb_ok(1'b1),
        .me_mem_ok(me_mem_ok),.me_clk_en(me_clk_en),
        .b_active(b_active),.b_cur(b_cur),.b_split_r(b_split_r),.b_ts_r(b_ts_r),.b_wcs_r(b_wcs_r),
        .b_xc(b_xc),.b_xcs_r(b_xcs_r),.b_wsrc_r(b_wsrc_r),.b_k(b_k),.b_ktot_r(b_ktot_r),
        .b_s1b_wsrc(b_s1b_wsrc),.b_s2_round(b_s2_round),.b_s3_v(b_s3_v),.b_fl_first4(b_fl_first4),
        .b_vline5(b_vline5),.b_reduce_valid(b_reduce_valid),.b_reduce_select(b_reduce_select),
        .b_pre_v(b_pre_v),.b_pre(b_pre),.b_raw_v(b_raw_v),.b_raw(b_raw),.b_r_v(b_r_v),.b_r(b_r),
        .x_scale_any(x_scale_any),.x_group_fault_q(x_group_fault_q),.x_scale_fault(x_scale_fault),
        .x_tfault(x_tfault),.x_top(x_top));

    ot_rom_tp_seq #(.N(D),.NW(SNW),.PAW(PAW),.VWA(8),.DAW(DAW),.FW(FW),.TAGW(32),
                    .QWEN_FULLSHAPE(QWEN_FULLSHAPE)) seq (
        .clk(clk),.rst_n(rst_n),.start(start | h_start),.token(tp_token),.pos(tp_pos),
        .done(s_done),.next_token(seq_ntok),.next_val(seq_nval),
        .fault(s_fault),.coll_busy(coll_busy),
        .core_start(core_start),.core_token(core_tok),.core_pos(core_pos),
        .core_done(core_done),.core_next_token(core_ntok),.core_next_val(core_nval),
        .core_fault(core_fault),.prog_base(prog_base),
        .desc_re(desc_re),.desc_addr(desc_addr),.desc_q(desc_q),
        .vm_re(s_vre),.vm_raddr(s_vraddr),.vm_rq(s_vrq),
        .vm_we(s_vwe),.vm_waddr(s_vwaddr),.vm_wdata(s_vwdata),
        .c_valid(c_valid),.c_ready(c_ready),.c_data(c_data),
        .c_last(c_last),.c_mode(c_mode),.c_tag(c_tag),
        .r_valid(r_valid),.r_data(r_data),.r_last(r_last),
        .r_rank(r_rank),.r_err(r_err));
endmodule
